-- sequencia (20)
on conflict do nothing;

-- roteiros (6)
on conflict (nome) do nothing;

select 'sequências' as o_que, count(*) from public.cartas where tipo = 'sequencia' and sala is null
union all select 'roteiros', count(*) from public.roteiros;
